const body = $input.first().json.body || $input.first().json;
const name = body.name || "Calzado Flores";
const category = body.category || "calzado";
const price = body.price ? `Bs. ${body.price}` : "Precio a consultar";
const imageUrl = body.imageUrl || "";

const promptText = `Sos el director de arte y redactor publicitario senior de FLORES (marca boliviana de calzado femenino de lujo, estética brutalista editorial, acento carmín #9B1C1C, sin amarillo, sobrio, elegante y transparente).

Producto: "${name}"
Categoría: "${category}"
Precio: ${price}
Foto de referencia: ${imageUrl}

Devuelve ÚNICAMENTE un objeto JSON válido (sin texto antes ni después) con esta estructura exacta:
{
  "flux_prompt": "Ultra-detailed high-end commercial footwear photography prompt in English for Flux-realism model. Describe the footwear with tactile texture, studio lighting with subtle crimson rim light, placed on dark minimalist brutalist pedestal, shot on 85mm f/1.4 lens, Vogue magazine cover quality, photorealistic 8k, sharp focus.",
  "nano_banana_prompt": "Detailed prompt in English specifically tailored for Google Nano Banana / Gemini 2.5 Flash Image. Instruct the model to place the exact footwear from the reference photo onto an elegant female model in a high-fashion editorial pose, wearing minimalist monochromatic attire, architectural lighting, sharp focus, 8k.",
  "tiktok": "Texto magnético y directo para TikTok sin urgencia falsa.",
  "instagram": "Caption editorial para Instagram con detalles del modelo y cómo pedir.",
  "whatsapp": "Mensaje de difusión para WhatsApp con precio ${price} y enlace a la tienda."
}`;

return {
  name,
  category,
  price,
  imageUrl,
  geminiPayload: {
    contents: [
      {
        parts: [
          { text: promptText }
        ]
      }
    ]
  }
};

const prev = $node['Preparar Prompt'].json;
const geminiRes = $input.first().json;

let cleanText = '';
try {
  cleanText = geminiRes.candidates[0].content.parts[0].text;
} catch (e) {
  cleanText = '{}';
}

cleanText = cleanText.trim();
if (cleanText.startsWith('```json')) cleanText = cleanText.substring(7);
if (cleanText.startsWith('```')) cleanText = cleanText.substring(3);
if (cleanText.endsWith('```')) cleanText = cleanText.substring(0, cleanText.length - 3);
cleanText = cleanText.trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  parsed = {
    flux_prompt: `luxury ${prev.category} footwear, high fashion editorial lighting, crimson aesthetic, 8k, sharp focus`,
    nano_banana_prompt: `Editorial fashion photo of a model wearing ${prev.name}, studio lighting, high resolution`,
    tiktok: `Descubre ${prev.name} en Flores Store.`,
    instagram: `${prev.name} — Calzado con stock real en Bolivia. Precio: ${prev.price}`,
    whatsapp: `¡Nuevo ingreso! ${prev.name} a ${prev.price}. Pide el tuyo por WhatsApp.`
  };
}

const fluxEncoded = encodeURIComponent(parsed.flux_prompt);
const randomSeed = Math.floor(Math.random() * 100000);
const pollinationsUrl = `https://image.pollinations.ai/prompt/${fluxEncoded}?width=800&height=1000&model=flux-realism&nologo=true&seed=${randomSeed}`;

return {
  name: prev.name,
  category: prev.category,
  price: prev.price,
  imageUrl: prev.imageUrl,
  flux_prompt: parsed.flux_prompt,
  nano_banana_prompt: parsed.nano_banana_prompt,
  tiktok: parsed.tiktok,
  instagram: parsed.instagram,
  whatsapp: parsed.whatsapp,
  poster_url: pollinationsUrl
};

